    @R("signal", "ip", "p")
    def _signal(c, sig, fn):
        prev = getattr(crt, "signals", {}).get(sig, 0)
        crt.signals = getattr(crt, "signals", {})
        crt.signals[sig] = fn
        return prev

    @R("raise", "i")
    def _raise(c, sig):
        fn = getattr(crt, "signals", {}).get(sig, 0)
        if fn in (0,):
            if sig in (2, 22, 11, 8, 4, 15):
                raise NOOExitProcess(3)
            return 0
        if fn == 1:
            return 0
        crt.call(fn, [sig])
        return 0

