    @R("strcat_s", "pzp")
    def _strcat_s(c, d, n, s):
        cur = crt.cs(d)
        b = crt.cs(s)
        if len(cur) + len(b) + 1 > n:
            if d and n:
                c.mem.write8(d, 0)
            return _ERANGE
        crt.put_cs(d + len(cur), b)
