    @R("strncat_s", "pzpz")
    def _strncat_s(c, d, dn, s, n):
        cur = crt.cs(d)
        b = c.mem.read_cstring(s, n if n < (1 << 31) else 1 << 30)
        if len(cur) + len(b) + 1 > dn:
            if d and dn:
                c.mem.write8(d, 0)
            return _ERANGE
        crt.put_cs(d + len(cur), b)
