    def _strtok(c, s, delim):
        return _tok(c, s, delim, "strtok_ptr")

    @R("strtok_s strtok_r", "ppp", "p")
    def _strtok_s(c, s, delim, ctx):
        return _tok(c, s, delim, "strtok_ptr", ctx)

