        if b < 0x80:
            return b
        need = 1 if b < 0xE0 else (2 if b < 0xF0 else 3)
        raw = bytes([b]) + bytes(max(0, crt.f_getc(cf)) for _ in range(need))
        return ord(raw.decode("utf-8", "replace")[0]) & 0xFFFF

