    @R("fgets", "pip", "p")
    def _fgets(c, buf, n, fp):
        cf = crt.fget(fp)
        if cf is None or n <= 0:
            return 0
        out = bytearray()
        while len(out) < n - 1:
            ch = crt.f_getc(cf)
            if ch < 0:
                break
            out.append(ch)
            if ch == 10:
                break
        if not out:
            return 0
        crt.put_cs(buf, out)
        return buf

