    def _fseek_impl(fp, off, whence):
        cf = crt.fget(fp)
        if cf is None:
            return -1
        fdo = crt.fds.get(cf.fd)
        if fdo is None or fdo.kind != "file":
            crt.set_errno(_EINVAL)
            return -1
        if whence == 1:
            off -= len(cf.unget)
        cf.unget = []
        try:
            fdo.f.seek(off, whence)
        except (OSError, ValueError):
            crt.set_errno(_EINVAL)
            return -1
        cf.eof = False
        fdo.eof = False
        return 0

