    def _ftell_impl(fp):
        cf = crt.fget(fp)
        if cf is None:
            return -1
        fdo = crt.fds.get(cf.fd)
        if fdo is None or fdo.kind != "file":
            return -1
        return fdo.f.tell() - len(cf.unget)

