    def _rename_impl(a, b):
        try:
            src = p.vfs.resolve(a, for_write=True)
            dst = p.vfs.resolve(b, for_write=True)
            if os.path.exists(dst):
                crt.set_errno(_EACCES)
                return -1
            os.rename(src, dst)
            return 0
        except Exception as e:
            crt.set_errno(crt._map_oserr(e))
            return -1

