    @R("strftime _strftime_l", "pzpp", "z")
    def _strftime(c, buf, n, fmt, tm):
        s = _crt_strftime(crt.cs(fmt).decode("latin-1"), _read_tm(tm)).encode("latin-1", "replace")
        if len(s) + 1 > n:
            return 0
        crt.put_cs(buf, s)
        return len(s)

    @R("wcsftime _wcsftime_l", "pzpp", "z")
    def _wcsftime(c, buf, n, fmt, tm):
        s = _crt_strftime(crt.ws(fmt), _read_tm(tm))
        if len(s) + 1 > n:
            return 0
        crt.put_ws(buf, s)
        return len(s)

    @R("_strdate", "p", "p")
    def __strdate(c, buf):
        crt.put_cs(buf, time.strftime("%m/%d/%y").encode())
        return buf

    @R("_strtime", "p", "p")
    def __strtime(c, buf):
        crt.put_cs(buf, time.strftime("%H:%M:%S").encode())
        return buf

    @R("_tzset", "", "v")
    def __tzset(c):
        return None

    def _tz_cell(name, init):
        a = crt.data_addrs.get(("msvcrt.dll", name), 0)
        if not a:                                   # UCRT-only programs: own cells
            a = crt.static_bufs.get(name)
            if a is None:
                a = crt.alloc(max(8, len(init)))
                p.mem.write(a, init)
                crt.static_bufs[name] = a
        return a

    R("__p__timezone __timezone", "", "p")(lambda c: _tz_cell("_timezone", struct.pack("<i", 0)))
    R("__p__daylight __daylight", "", "p")(lambda c: _tz_cell("_daylight", struct.pack("<i", 0)))
    R("__p__dstbias __dstbias", "", "p")(lambda c: _tz_cell("_dstbias", struct.pack("<i", -3600)))

    @R("__p__tzname __tzname", "", "p")
    def __p_tzname(c):
        a = crt.data_addrs.get(("msvcrt.dll", "_tzname"), 0)
        if a:
            return a
        a = crt.static_bufs.get("_tzname")
        if a is None:
            ps = 8 if p.cpu_mode == 64 else 4
            strs = crt.alloc(32)
            p.mem.write(strs, b"UTC\0" + bytes(12) + b"UTC\0" + bytes(12))
            a = crt.alloc(2 * ps)
            crt.wptr(a, strs)
            crt.wptr(a + ps, strs + 16)
            crt.static_bufs["_tzname"] = a
        return a

    @R("_get_dstbias", "p")
    def __get_dstbias(c, out):
        c.mem.write32(out, (-3600) & 0xFFFFFFFF)
        return 0

    @R("_get_tzname", "ppzi")
    def __get_tzname(c, pret, buf, n, idx):
        t = b"UTC"
        if pret:
            crt.wptr(pret, len(t) + 1)
        if buf and n > len(t):
            p.mem.write(buf, t + b"\0")
        return 0

    @R("_get_timezone", "p")
    def __get_timezone(c, out):
        c.mem.write32(out, 0)
        return 0

    @R("_get_daylight", "p")
    def __get_daylight(c, out):
        c.mem.write32(out, 0)
        return 0

    @R("_ftime _ftime64 _ftime32 _ftime_s _ftime64_s", "p")
    def __ftime(c, buf):
        t = time.time()
        if crt.x64 or True:
            c.mem.write(buf, struct.pack("<qHhh", int(t), int((t % 1) * 1000), 0, 0))
        return 0

    @R("timespec_get _timespec64_get", "pi")
    def _timespec_get(c, ts, base):
        t = time.time()
        c.mem.write(ts, struct.pack("<qi", int(t), int((t % 1) * 1e9)))
        return base

    @R("_sleep", "u", "v")
    def __sleep(c, ms):
        time.sleep(min(ms, 5000) / 1000.0)

    # threads through the CRT ------------------------------------------------------
    @R("_beginthreadex", "ppppup", "p")
    def __beginthreadex(c, sec, stack, start, arg, flags, ptid):
        tid, h = p.create_thread(start, arg, stack or 0x100000)
        if ptid:
            c.mem.write32(ptid, tid)
        return h

    @R("_beginthread", "ppp", "p")
    def __beginthread(c, start, stack, arg):
        tid, h = p.create_thread(start, arg, stack or 0x100000)
        return h

    @R("_endthread _endthreadex", "u", "v")
    def __endthread(c, code):
        raise NOOExitThread(code)

    return crt



