    def _setevent(c, h):
        ev = p.handles.get(h, "kevent")
        if ev is None:
            old = p.handles.get(h, "event")
            if old is not None:
                old["signaled"] = True
                return 1
            return k.err(ERROR_INVALID_HANDLE)
        ev.signaled = True
        return 1

    @R("SetEvent", "p")
    def _setev(c, h):
        return _setevent(c, h)

    @R("ResetEvent", "p")
    def _resetev(c, h):
        ev = p.handles.get(h, "kevent")
        if ev is None:
            old = p.handles.get(h, "event")
            if old is not None:
                old["signaled"] = False
                return 1
            return k.err(ERROR_INVALID_HANDLE)
        ev.signaled = False
        return 1

    @R("PulseEvent", "p")
    def _pulseev(c, h):
        ev = p.handles.get(h, "kevent")
        if ev is None:
            return k.err(ERROR_INVALID_HANDLE)
        # release waiters currently blocked, then reset
        for t in p.threads:
            w = t.waiting_on
            if t.state == "blocked" and w and w[0] == "kwait" and h in w[1]:
                ev.signaled = True
                if k.wake_check(t):
                    t.state = "running"
                    t.waiting_on = None
                    t.cpu.finish_yield()
                    if not ev.manual:
                        break
        ev.signaled = False
        return 1

    def _cmutex(c, owned, name, wide):
        def make():
            m_ = _KMutex()
            if owned:
                m_.owner = p.current_thread.tid
                m_.count = 1
            return m_
        return _create_named("kmutex", _named(name, wide), make)

