    @R("ReleaseMutex", "p")
    def _relmx(c, h):
        m_ = p.handles.get(h, "kmutex")
        if m_ is None:
            old = p.handles.get(h, "mutex")
            if old is not None:
                old["owned"] = False
                return 1
            return k.err(ERROR_INVALID_HANDLE)
        if m_.owner != p.current_thread.tid:
            return k.err(ERROR_NOT_OWNER)
        m_.count -= 1
        if m_.count <= 0:
            m_.count = 0
            m_.owner = 0
        return 1

