    @R("GetLogicalDrives", "")
    def _gld(c):
        m_ = 0
        for d in _drives():
            m_ |= 1 << (ord(d) - 65)
        return m_

    def _glds(n, buf, wide):
        s_ = "".join("%s:\\\0" % d for d in _drives())
        data = s_.encode("utf-16-le") if wide else s_.encode()
        units = len(s_)
        if n < units + 1 or not buf:
            return units + 1
        p.mem.write(buf, data + (b"\0\0" if wide else b"\0"))
        return units

