    def _gvi(root, vn, vns, serial, maxc, fsf, fsn, fsns, wide):
        if root and _gdt(root) == 1:
            return k.err(ERROR_PATH_NOT_FOUND)
        if vn and vns:
            k.put(vn, vns, "NOO", wide)
        w32(serial, 0x4E4F4F21)
        w32(maxc, 255)
        w32(fsf, 0x03E700FF)
        if fsn and fsns:
            k.put(fsn, fsns, "NTFS", wide)
        return 1

