    @R("SetStdHandle", "up")
    def _ssh(c, n, h):
        if n & 0xFFFFFFFF not in (0xFFFFFFF6, 0xFFFFFFF5, 0xFFFFFFF4):
            return k.err(ERROR_INVALID_HANDLE)
