    # =====================================================================
    # user32 text helpers (Char*, IsChar*, wsprintf)
    # =====================================================================
    U32 = ("user32.dll",)

    def _case_str(a, wide, fn):
        if a < 0x10000:                             # a single character
            return ord(fn(chr(a & 0xFFFF))[:1] or chr(a & 0xFFFF))
        if wide:
            s_ = k.ws_(a)
            p.mem.write(a, fn(s_).encode("utf-16-le")[:2 * len(s_)])
        else:
            raw = p.mem.read_cstring(a, 1 << 20)
            p.mem.write(a, fn(raw.decode("latin-1")).encode("latin-1", "replace")[:len(raw)])
        return a

    def _case_buf(a, n, wide, fn):
        if not a or not n:
            return 0
        if wide:
            s_ = p.mem.read(a, 2 * n).decode("utf-16-le", "replace")
            p.mem.write(a, fn(s_).encode("utf-16-le")[:2 * n])
        else:
            s_ = p.mem.read(a, n).decode("latin-1")
            p.mem.write(a, fn(s_).encode("latin-1", "replace")[:n])
        return n

    def _up(s_):
        return "".join(ch.upper() if len(ch.upper()) == 1 else ch for ch in s_)

    def _lo(s_):
        return "".join(ch.lower() if len(ch.lower()) == 1 else ch for ch in s_)

    @R("CharUpperA", "p", "p", dlls=U32)
    def _cua(c, a):
        return _case_str(a, False, _up)

    @R("CharUpperW", "p", "p", dlls=U32)
    def _cuw(c, a):
        return _case_str(a, True, _up)

    @R("CharLowerA", "p", "p", dlls=U32)
    def _cla(c, a):
        return _case_str(a, False, _lo)

    @R("CharLowerW", "p", "p", dlls=U32)
    def _clw(c, a):
        return _case_str(a, True, _lo)

    @R("CharUpperBuffA", "pu", dlls=U32)
    def _cuba(c, a, n):
        return _case_buf(a, n, False, _up)

    @R("CharUpperBuffW", "pu", dlls=U32)
    def _cubw(c, a, n):
        return _case_buf(a, n, True, _up)

    @R("CharLowerBuffA", "pu", dlls=U32)
    def _clba(c, a, n):
        return _case_buf(a, n, False, _lo)

    @R("CharLowerBuffW", "pu", dlls=U32)
    def _clbw(c, a, n):
        return _case_buf(a, n, True, _lo)

    @R("CharNextA", "p", "p", dlls=U32)
    def _cna(c, a):
        return a + 1 if p.mem.read8(a) else a

    @R("CharNextW", "p", "p", dlls=U32)
    def _cnw(c, a):
        return a + 2 if p.mem.read16(a) else a

    @R("CharNextExA", "ppu", "p", dlls=U32)
    def _cnxa(c, cp, a, fl):
        return a + 1 if p.mem.read8(a) else a

    @R("CharPrevA", "pp", "p", dlls=U32)
    def _cpa(c, start, a):
        return a - 1 if a > start else start

    @R("CharPrevW", "pp", "p", dlls=U32)
    def _cpw2(c, start, a):
        return a - 2 if a > start else start

    @R("CharPrevExA", "pppu", "p", dlls=U32)
    def _cpxa(c, cp, start, a, fl):
        return a - 1 if a > start else start

    def _ischar(ch, wide, test):
        ch &= 0xFFFF if wide else 0xFF
        s_ = chr(ch) if wide else bytes([ch]).decode("cp1252", "replace")
        return 1 if test(s_) else 0

    for nm, test in (("IsCharAlpha", str.isalpha), ("IsCharUpper", str.isupper),
                     ("IsCharLower", str.islower), ("IsCharAlphaNumeric", str.isalnum)):
        R(nm + "A", "u", dlls=U32)(lambda c, ch, _t=test: _ischar(ch, False, _t))
        R(nm + "W", "u", dlls=U32)(lambda c, ch, _t=test: _ischar(ch, True, _t))

    def _oem(src, dst, n, wide_src, wide_dst):
        if n is None:
            s_ = k.ws_(src) if wide_src else p.mem.read_cstring(src, 1 << 20).decode("latin-1")
            term = True
        else:
            s_ = p.mem.read(src, 2 * n).decode("utf-16-le", "replace") if wide_src else \
                p.mem.read(src, n).decode("latin-1")
            term = False
        data = s_.encode("utf-16-le") if wide_dst else s_.encode("latin-1", "replace")
        if term:
            data += b"\0\0" if wide_dst else b"\0"
        p.mem.write(dst, data)
        return 1

    @R("CharToOemA OemToCharA AnsiToOem OemToAnsi", "pp", dlls=U32)
    def _ctoa(c, s_, d):
        return _oem(s_, d, None, False, False)

    @R("CharToOemW", "pp", dlls=U32)
    def _ctow(c, s_, d):
        return _oem(s_, d, None, True, False)

    @R("OemToCharW", "pp", dlls=U32)
    def _otcw(c, s_, d):
        return _oem(s_, d, None, False, True)

    @R("CharToOemBuffA OemToCharBuffA", "ppu", dlls=U32)
    def _ctoba(c, s_, d, n):
        return _oem(s_, d, n, False, False)

    @R("CharToOemBuffW", "ppu", dlls=U32)
    def _ctobw(c, s_, d, n):
        return _oem(s_, d, n, True, False)

    @R("OemToCharBuffW", "ppu", dlls=U32)
    def _otcbw(c, s_, d, n):
        return _oem(s_, d, n, False, True)

    def _wsprintf(buf, fmt_ptr, args, wide):
        m_ = p.mem
        if wide:
            fmt = k.ws_(fmt_ptr)
            text = _crt_printf(fmt, args, "msvcrt", True,
                               get_str=lambda a, n=None: m_.read_cstring(a, 1 << 20 if n is None or n < 0 else n).decode("latin-1"),
                               get_wstr=lambda a, n=None: m_.read_wstring(a, 1 << 20 if n is None or n < 0 else n).decode("utf-16-le", "replace"),
                               ptr_size=k.ptr_size())
            text = text[:1024]
            m_.write(buf, text.encode("utf-16-le") + b"\0\0")
        else:
            fmt = m_.read_cstring(fmt_ptr, 1 << 20).decode("latin-1")
            text = _crt_printf(fmt, args, "msvcrt", False,
                               get_str=lambda a, n=None: m_.read_cstring(a, 1 << 20 if n is None or n < 0 else n).decode("latin-1"),
                               get_wstr=lambda a, n=None: m_.read_wstring(a, 1 << 20 if n is None or n < 0 else n).decode("utf-16-le", "replace"),
                               ptr_size=k.ptr_size())
            text = text[:1024]
            m_.write(buf, text.encode("latin-1", "replace") + b"\0")
        return len(text)

    @R("wsprintfA", "pp.", dlls=U32)
    def _wspa(c, buf, fmt, va):
        return _wsprintf(buf, fmt, va, False)

    @R("wsprintfW", "pp.", dlls=U32)
    def _wspw(c, buf, fmt, va):
        return _wsprintf(buf, fmt, va, True)

    @R("wvsprintfA", "ppp", dlls=U32)
    def _wvspa(c, buf, fmt, va):
        return _wsprintf(buf, fmt, _VaList(c, va), False)

    @R("wvsprintfW", "ppp", dlls=U32)
    def _wvspw(c, buf, fmt, va):
        return _wsprintf(buf, fmt, _VaList(c, va), True)

    # =====================================================================
    # waitable timers
    # =====================================================================
    class _KTimer:
        def __init__(self, manual):
            self.manual = bool(manual)
            self.signaled = False
            self.due = None               # time.monotonic() deadline
            self.period = 0.0             # seconds

        def ready(self, take):
            now = time.monotonic()
            if not self.signaled and self.due is not None and now >= self.due:
                self.signaled = True
                if self.period:
                    self.due = max(self.due + self.period, now)
                else:
                    self.due = None
            if self.signaled:
                if take and not self.manual:
                    self.signaled = False
                return True
            return False

    def _ctimer(manual, name):
        return _create_named("ktimer", name, lambda: _KTimer(manual))

    @R("CreateWaitableTimerA", "pip", "p")
    def _cwta(c, sa, manual, name):
        return _ctimer(manual, k.cs_(name) if name else None)

    @R("CreateWaitableTimerW", "pip", "p")
    def _cwtw(c, sa, manual, name):
        return _ctimer(manual, k.ws_(name) if name else None)

    @R("CreateWaitableTimerExA", "ppuu", "p")
    def _cwtxa(c, sa, name, flags, acc):
        return _ctimer(flags & 1, k.cs_(name) if name else None)

    @R("CreateWaitableTimerExW", "ppuu", "p")
    def _cwtxw(c, sa, name, flags, acc):
        return _ctimer(flags & 1, k.ws_(name) if name else None)

    @R("OpenWaitableTimerA", "uip", "p")
    def _owta(c, acc, inh, name):
        return _open_named("ktimer", k.cs_(name))

    @R("OpenWaitableTimerW", "uip", "p")
    def _owtw(c, acc, inh, name):
        return _open_named("ktimer", k.ws_(name))

    def _set_timer(h, pdue, period):
        tm = p.handles.get(h, "ktimer")
        if tm is None:
            return k.err(ERROR_INVALID_HANDLE)
        due = _s64(p.mem.read64(pdue))
        now = time.monotonic()
        if due < 0:
            delay = -due / 10_000_000.0
        else:
            delay = max(0.0, _unix_from_ft(due) - time.time())
        tm.due = now + delay
        tm.period = (period & 0x7FFFFFFF) / 1000.0
        tm.signaled = False
        p.last_error = 0
        return 1

    k.KTimer, k.set_timer = _KTimer, _set_timer

    @R("SetWaitableTimer", "ppippi")
    def _swt(c, h, pdue, period, cb, arg, resume):
        return _set_timer(h, pdue, period)

    @R("SetWaitableTimerEx", "ppipppu")
    def _swtx(c, h, pdue, period, cb, arg, wake, delay):
        return _set_timer(h, pdue, period)

    @R("CancelWaitableTimer", "p")
    def _cancwt(c, h):
        tm = p.handles.get(h, "ktimer")
        if tm is None:
            return k.err(ERROR_INVALID_HANDLE)
        tm.due = None
        return 1

    # pool timers and waits: timer queues, RegisterWaitForSingleObject, TP timers / waits ---
    # Each armed item runs on its own worker thread, which alternates a real Sleep /
    # WaitForSingleObject with calls to the callback on a fixed stack frame.
    k.pool_items = {}
    k.pool_next = [1]
    k.pool_by_ptr = {}                      # TP_TIMER / TP_WAIT pointer -> item id
    k.tq_members = {}                       # timer queue handle -> [item ids]

    def _pool_entry(c):
        t = p.current_thread
        iid = t.__dict__.get("pool_item")
        if iid is None:
            iid = _CallArgs(c).int()
            t.pool_item = iid
            t.pool_sp = (c.regs[RSP] - 0x200) & ~0xF
            t.pool_phase = None
        it = k.pool_items.get(iid)
        if it is None or it["dead"]:
            k.pool_items.pop(iid, None)
            raise NOOExitThread(0)
        entry = k.pool_entry_thunk
        now = time.monotonic()
        if it["kind"] == "wait":
            if t.pool_phase == "waited":
                t.pool_phase = None
                r = c.regs[RAX] & 0xFFFFFFFF
                expired = it["deadline"] is not None and now >= it["deadline"]
                if it["handle"] is not None and (r == 0 or expired):
                    args = it["args"](r != 0)
                    if it["once"]:
                        it["handle"] = None if it.get("tp") else it["handle"]
                        if not it.get("tp"):
                            it["dead"] = True
                    elif it["timeout"] is not None:
                        it["deadline"] = now + it["timeout"]
                    p.seh._call(c, it["cb"], args, entry, t.pool_sp)
                    raise NOOContextSet()
            if it["handle"] is None:
                p.seh._call(c, k.pool_sleep, [100], entry, t.pool_sp)
                raise NOOContextSet()
            dl = it["deadline"]
            ms = 100 if dl is None else max(0, min(100, int((dl - now) * 1000) + 1))
            t.pool_phase = "waited"
            p.seh._call(c, k.pool_wait, [it["handle"], ms], entry, t.pool_sp)
            raise NOOContextSet()
        nxt = it["next"]
        if nxt is None or now < nxt:
            ms = 100 if nxt is None else max(1, min(100, int((nxt - now) * 1000) + 1))
            p.seh._call(c, k.pool_sleep, [ms], entry, t.pool_sp)
            raise NOOContextSet()
        if it["period"]:
            it["next"] = max(nxt + it["period"], now)
        else:
            it["next"] = None
            if it.get("once_dead"):
                it["dead"] = True
        p.seh._call(c, it["cb"], it["args"](True), entry, t.pool_sp)
        raise NOOContextSet()

    _pool_entry._noo_cc = "cdecl"
    api.table[("!noo!", "pool_entry")] = _pool_entry
    k.pool_entry_thunk = 0

    def pool_start(item):
        if not k.pool_entry_thunk:
            k.pool_entry_thunk = p.api_thunk("!noo!", "pool_entry")
            k.pool_sleep = p.api_thunk("kernel32.dll", "Sleep")
            k.pool_wait = p.api_thunk("kernel32.dll", "WaitForSingleObject")
        iid = k.pool_next[0]
        k.pool_next[0] += 1
        item.setdefault("dead", False)
        k.pool_items[iid] = item
        p.create_thread(k.pool_entry_thunk, iid, 0x40000)
        return iid

    def ms_or_none(ms):
        return None if ms in (INFINITE, 0xFFFFFFFF) else ms / 1000.0

    # timer queues
    @R("CreateTimerQueue", "", "p")
    def _ctq(c):
        h = p.handles.add({"timers": []}, "timerq")
        k.tq_members[h] = []
        return h

    def tq_timer(queue, cb, param, due, period, once):
        item = {"kind": "timer", "cb": cb, "args": lambda to, _p=param: [_p, 1],
                "next": time.monotonic() + due / 1000.0, "period": period / 1000.0,
                "once_dead": not period}
        iid = pool_start(item)
        h = p.handles.add(item, "tqtimer")
        k.tq_members.setdefault(queue, []).append(iid)
        return h

    @R("CreateTimerQueueTimer", "ppppuuu")
    def _ctqt(c, ph, queue, cb, param, due, period, flags):
        if not ph or not cb:
            return k.err(ERROR_INVALID_PARAMETER)
        k.wptr(ph, tq_timer(queue, cb, param, due, period, flags & 8))
        return 1

    @R("DeleteTimerQueueTimer", "ppp")
    def _dtqt(c, q, t_, ev):
        ent = p.handles.get(t_, "tqtimer")
        if ent is not None:
            ent["dead"] = True
        if ev and ev not in (0xFFFFFFFF, M64):
            e = p.handles.get(ev, "kevent")
            if e is not None:
                e.signaled = True
        return 1

    @R("ChangeTimerQueueTimer", "ppuu")
    def _chtqt(c, q, t_, due, period):
        ent = p.handles.get(t_, "tqtimer")
        if ent is not None:
            ent["next"] = time.monotonic() + due / 1000.0
            ent["period"] = period / 1000.0
            ent["once_dead"] = False
        return 1

    def tq_delete(q):
        for iid in k.tq_members.pop(q, []):
            it = k.pool_items.get(iid)
            if it is not None:
                it["dead"] = True
        return 1

    @R("DeleteTimerQueue", "p")
    def _dtq1(c, h):
        return tq_delete(h)

    @R("DeleteTimerQueueEx", "pp")
    def _dtq(c, h, ev):
        tq_delete(h)
        if ev and ev not in (0xFFFFFFFF, M64):
            e = p.handles.get(ev, "kevent")
            if e is not None:
                e.signaled = True
        return 1

    NT_ = ("ntdll.dll",)

    @R("RtlCreateTimerQueue", "p", "u", NT_)
    def _rctq(c, ph):
        k.wptr(ph, _ctq(c))
        return 0

    @R("RtlCreateTimer", "ppppuuu", "u", NT_)
    def _rct(c, queue, ph, cb, ctx, due, period, flags):
        k.wptr(ph, tq_timer(queue, cb, ctx, due, period, flags & 8))
        return 0

    R("RtlUpdateTimer", "ppuu", "u", NT_)(lambda c, q, t_, due, per: (_chtqt(c, q, t_, due, per),
                                                                     0)[1])
    R("RtlDeleteTimer", "ppp", "u", NT_)(lambda c, q, t_, ev: (_dtqt(c, q, t_, ev), 0)[1])
    R("RtlDeleteTimerQueueEx", "pp", "u", NT_)(lambda c, q, ev: (_dtq(c, q, ev), 0)[1])
    R("RtlDeleteTimerQueue", "p", "u", NT_)(lambda c, q: (tq_delete(q), 0)[1])

    # registered waits
    def reg_wait(hobj, cb, ctx, ms, flags):
        to = ms_or_none(ms)
        item = {"kind": "wait", "cb": cb, "handle": hobj,
                "args": lambda timed_out, _c=ctx: [_c, 1 if timed_out else 0],
                "timeout": to, "deadline": (time.monotonic() + to) if to is not None else None,
                "once": bool(flags & 8)}
        pool_start(item)
        return p.handles.add(item, "regwait")

    @R("RegisterWaitForSingleObject", "pppppu")
    def _rwfso(c, ph, hobj, cb, ctx, ms, flags):
        if not ph or not cb:
            return k.err(ERROR_INVALID_PARAMETER)
        k.wptr(ph, reg_wait(hobj, cb, ctx, ms, flags))
        return 1

    R("RegisterWaitForSingleObjectEx", "pppuu", "p")(
        lambda c, hobj, cb, ctx, ms, flags: reg_wait(hobj, cb, ctx, ms, flags))

    def unreg(h):
        it = p.handles.get(h, "regwait")
        if it is None:
            return k.err(ERROR_INVALID_HANDLE)
        it["dead"] = True
        return 1

    R("UnregisterWait", "p")(lambda c, h: unreg(h))
    R("UnregisterWaitEx", "pp")(lambda c, h, ev: unreg(h))
    R("RtlRegisterWait", "pppppu", "u", NT_)(
        lambda c, ph, hobj, cb, ctx, ms, flags: (k.wptr(ph, reg_wait(hobj, cb, ctx, ms, flags)),
                                                 0)[1])
    R("RtlDeregisterWait RtlDeregisterWaitEx", "pp", "u", NT_)(
        lambda c, h, ev=0: (unreg(h), 0)[1])

    # threadpool timers and waits (Vista API)
    def tp_new(kind, cb, pv):
        ptr = p.heap_alloc(p.process_heap_handle, 32)
        if kind == "timer":
            item = {"kind": "timer", "cb": cb, "next": None, "period": 0.0, "tp": True,
                    "args": lambda to, _p=pv, _t=ptr: [0, _p, _t]}
        else:
            item = {"kind": "wait", "cb": cb, "handle": None, "timeout": None,
                    "deadline": None, "once": True, "tp": True, "result": 0}
            item["args"] = lambda to, _p=pv, _t=ptr: [0, _p, _t, 0x102 if to else 0]
        k.pool_by_ptr[ptr] = pool_start(item)
        return ptr

    def tp_item(ptr):
        iid = k.pool_by_ptr.get(ptr)
        return k.pool_items.get(iid) if iid is not None else None

    def ft_due(pft):
        """PFILETIME due time -> monotonic deadline."""
        v = _s64(p.mem.read64(pft))
        if v < 0:
            return time.monotonic() + (-v) / 10_000_000.0
        if v == 0:
            return time.monotonic()
        return time.monotonic() + max(0.0, _unix_from_ft(v) - time.time())

    R("CreateThreadpoolTimer", "ppp", "p")(lambda c, cb, pv, env: tp_new("timer", cb, pv))
    R("CreateThreadpoolWait", "ppp", "p")(lambda c, cb, pv, env: tp_new("wait", cb, pv))

    def set_tp_timer(timer, pft, period):
        it = tp_item(timer)
        if it is None:
            return 0
        was = it["next"] is not None
        if not pft:
            it["next"] = None
        else:
            it["next"] = ft_due(pft)
            it["period"] = period / 1000.0
        return 1 if was else 0

    R("SetThreadpoolTimer", "ppuu", "v")(lambda c, t_, pft, per, win: set_tp_timer(t_, pft, per))
    R("SetThreadpoolTimerEx", "ppuu")(lambda c, t_, pft, per, win: set_tp_timer(t_, pft, per))
