    def new_sid(text):
        b = _sid_bytes(text)
        a = p.heap_alloc(p.process_heap_handle, len(b))
        M_.write(a, b)
        return a

    def read_sid(a):
        n = M_.read8(a + 1)
        return M_.read(a, 8 + 4 * n)

    def sid_text(a):
        try:
            return _sid_str(read_sid(a))
        except Exception:
            return ""

