    def lpn(luid, buf, pcch, wide):
        v = M_.read32(luid)
        for nm, val in _PRIVS.items():
            if val == v:
                cap = M_.read32(pcch)
                if cap < len(nm) + 1:
                    M_.write32(pcch, len(nm) + 1)
                    return k.err(ERROR_INSUFFICIENT_BUFFER)
                k.put(buf, cap, nm, wide)
                M_.write32(pcch, len(nm))
                return 1
        return k.err(1313)

