    def sid_to_str(sid, out, wide):
        txt = sid_text(sid)
        if not txt:
            return k.err(1337)                      # ERROR_INVALID_SID
        data = txt.encode("utf-16-le") + b"\0\0" if wide else txt.encode() + b"\0"
        a = p.heap_alloc(p.process_heap_handle, len(data))
        M_.write(a, data)
        k.wptr(out, a)
        return 1

