    def sid_to_str_sd(pout, plen, wide):
        txt = "O:BAG:BAD:(A;;GA;;;WD)"
        data = txt.encode("utf-16-le") + b"\0\0" if wide else txt.encode() + b"\0"
        a = p.heap_alloc(p.process_heap_handle, len(data))
        M_.write(a, data)
        k.wptr(pout, a)
        if plen:
            M_.write32(plen, len(txt) + 1)
        return 1

