    @R("MapGenericMask", "pp", "v", dlls=_ADV)
    def _mgm(c, pmask, mapping):
        m_ = M_.read32(pmask)
        gr, gw, ge, ga = struct.unpack("<IIII", M_.read(mapping, 16))
        out = m_ & 0x0FFFFFFF
        if m_ & 0x80000000:
            out |= gr
        if m_ & 0x40000000:
            out |= gw
        if m_ & 0x20000000:
            out |= ge
        if m_ & 0x10000000:
            out |= ga
        M_.write32(pmask, out)

