        ent = p.handles.get(h, "crypthash")
        if ent is None:
            return k.err(ERROR_INVALID_HANDLE)
        k.wptr(out, p.handles.add({"h": ent["h"].copy(), "alg": ent["alg"]}, "crypthash"))
        return 1

