    def _dlgitem(h, cid):
        w = W(h)
        if w is None:
            return None
        cid &= 0xFFFFFFFF
        for ch in w.children:
            if (ch.id & 0xFFFFFFFF) == cid and not ch.dead:
                return ch
        for ch in w.children:
            if (ch.id & 0xFFFF) == (cid & 0xFFFF) and not ch.dead:
                return ch
        return None

