    # ---- kernel32 odds -------------------------------------------------------------------
    @R("MulDiv", "iii")
    def _muldiv(c, a, b, d):
        if d == 0:
            return -1
        v = a * b
        q = abs(v) + abs(d) // 2
        q //= abs(d)
        if (v < 0) != (d < 0):
            q = -q
        if not -2 ** 31 <= q < 2 ** 31:
            return -1
        return q

