    @reg("GdipCreateFromHDC", "pp")
    def _cfhdc(c, hdc, pp):
        if gdi.get(hdc, "dc") is None or not pp:
            return GP_INVALID if not hdc else 7
        put_ptr(pp, new_graphics(_GpGraphics(hdc=hdc)))
        return GP_OK

