_X86_STDCALL_BYTES = None


def _x86_argbytes(name):
    """Bytes an x86 stdcall export pops, or None if unknown (decoded on first use)."""
    global _X86_STDCALL_BYTES
    if _X86_STDCALL_BYTES is None:
        import zlib as _z
        import base64 as _b
        table = {}
        text = _z.decompress(_b.b64decode("".join(_X86_STDCALL_BLOB))).decode()
        for line in text.split("\n"):
            nbytes, _sp, names = line.partition(" ")
            nb = int(nbytes)
            for n in names.split():
                table[n] = nb
        _X86_STDCALL_BYTES = table
    return _X86_STDCALL_BYTES.get(name.lower())


class NOOModule:
    __slots__ = ("name", "base", "size", "kind", "pe", "exports", "export_ordinals",
                 "forwarders")

    def __init__(self, name, base, size, kind, pe=None):
        self.name, self.base, self.size, self.kind, self.pe = name, base, size, kind, pe
        self.exports = {}          # name -> absolute address
        self.export_ordinals = {}  # ordinal -> absolute address
        self.forwarders = {}       # name / ordinal -> "DLL.Name" or "DLL.#ord"


